    ploys: {
      strategy: [
        { name: "Denounce", desc: "Pick an enemy and roll a D3. In the Firefight phase, it can't activate or act until your opponent has activated that many operatives, or it's their last one. Costs 1 extra CP for each earlier use." },
        { name: "Intense Scrutiny", desc: "When an Agent picks targets, enemies within 4\" (instead of 2\") can't be in cover. They only lose their cover save within 2\"." },
        { name: "Quarry", desc: "Pick an enemy as your quarry for the turning point. Agents shooting, fighting or retaliating against it gain Ceaseless. When it's incapacitated, pick a new quarry." },
        { name: "Irrefutable Jurisdiction", desc: "When an Agent within 3\" of an objective is shot, re-roll one defense die. If it's contesting the objective, re-roll any dice showing one result of your choice instead." },
      ],
      firefight: [
        { name: "Absolute Authority", desc: "When your opponent uses a ploy that costs CP (not Command Re-roll), it has no effect, they get the CP back, and they can't use it again this turning point. Once per battle for each ploy." },
        { name: "Relentless in Pursuit", desc: "When an enemy within 2\" of a ready Agent moves, that Agent makes a free Reposition (ending within 2\" of the enemy) or a free Charge (ending in its control range)." },
        { name: "The Emperor's Will", desc: "When one is activated, ignore changes to that Agent's stats (including weapon stats) for the activation." },
        { name: "Intimidating Presence", desc: "When an enemy visible within 3\" of an Agent (6\" of a Mystic) does Pick Up Marker or a mission action (not Operate Hatch), it costs 1 extra AP." },
      ],
    },
