    factionRules: [
      { name: "Doctrina Imperatives", desc: "At the end of Select Operatives, pick one imperative as your Primary Mode. As a STRATEGIC GAMBIT, pick an imperative for your operatives until the Ready step of the next Strategy phase. Both its Optimization and its Deprecation apply. Once per battle, when you pick your Primary Mode, ignore its Deprecation." },
      { name: "Protector Imperative", desc: "Ranged weapons gain Ceaseless. Deprecation: melee weapons get a worse Hit by 1 (doesn't stack with being injured)." },
      { name: "Conqueror Imperative", desc: "Melee weapons gain Ceaseless. Deprecation: ranged weapons get a worse Hit by 1 (doesn't stack with being injured)." },
      { name: "Bulwark Imperative", desc: "Normal Dmg of 3 or more inflicts 1 less damage. Deprecation: -1\" Move." },
      { name: "Aggressor Imperative", desc: "+1\" Move. Deprecation: Save gets worse by 1." },
      { name: "Neutral Imperative", desc: "No effects." },
    ],
    ploys: {
      strategy: [
        { name: "Debilitating Irradiation", desc: "When an enemy under Rad-Saturation attacks a Vanguard, it gets -1 Normal Dmg (to a minimum of 3)." },
        { name: "Neurostatic Interference", desc: "Enemies within 6\" of a friendly Infiltrator can't re-roll attack dice." },
        { name: "Scouting Protocol", desc: "Each Ranger with a Conceal order more than 6\" from enemies makes a free Dash. You can't use this in the first turning point." },
        { name: "Accelerant Agents", desc: "Each Ruststalker can Fight twice in each activation, and one of those is free." },
      ],
      firefight: [
        { name: "Control Edict", desc: "On your turn to activate, a Leader and another ready operative visible within 3\" of it (only one Sicarian) activate one after the other before your opponent goes." },
        { name: "Scrapcode Overload", desc: "When an Infiltrator activates, or when it or an enemy within 3\" of it would Pick Up Marker or take a mission action (not Operate Hatch), use this. Until its next activation, when enemies contest a marker and at least one of them is within 3\" of it, their total APL counts as 1 lower." },
        { name: "Command Override", desc: "When an operative activates, give it a different imperative until the next Ready step." },
        { name: "Omnissiah's Imperative", desc: "Use during its activation, or when it's shot (at the end of the Roll Attack Dice step). Until the next Ready step, it gets a bonus based on its imperative. Protector: ranged weapons gain Severe. Conqueror: when fighting, after your first attack die, resolve another one straight away. Bulwark: improve Save by 1 and roll one extra defense die when shot. Aggressor: ignore the first 2\" of one climb. Neutral: nothing." },
      ],
    },
